39	void bindToCore(int core_id) {
40	    cpu_set_t cpuset;
41	    CPU_ZERO(&cpuset);
42	    CPU_SET(core_id, &cpuset);
43	
44	    pthread_t current_thread = pthread_self();
45	    int rc = pthread_setaffinity_np(current_thread, sizeof(cpu_set_t), &cpuset);
46	    if (rc != 0) {
47	        std::cerr << "Error calling pthread_setaffinity_np: " << rc << "\n";
48	    }
49	}
