51	void bindToCore(std::vector<int> core_ids) {
52	    cpu_set_t cpuset;
53	    CPU_ZERO(&cpuset);
54	    for(int core_id : core_ids) {
55	        CPU_SET(core_id, &cpuset);
56	    }
57	
58	    pthread_t current_thread = pthread_self();
59	    int rc = pthread_setaffinity_np(current_thread, sizeof(cpu_set_t), &cpuset);
60	    if (rc != 0) {
61	        std::cerr << "Error calling pthread_setaffinity_np: " << rc << "\n";
62	    }
63	}
