65	void print_current_thread_affinity() {
66	    cpu_set_t cpuset;
67	    CPU_ZERO(&cpuset);
68	
69	    // Get affinity of the current calling thread
70	    pthread_t current_thread = pthread_self();
71	    int result = pthread_getaffinity_np(current_thread, sizeof(cpu_set_t), &cpuset);
72	    
73	    if (result != 0) {
74	        std::cerr << "Error getting affinity mask" << std::endl;
75	        return;
76	    }
77	
78	    // Print out which CPUs are available to this thread
79	    std::cout << "Thread is allowed to run on CPUs: ";
80	    for (int i = 0; i < CPU_SETSIZE; i++) {
81	        if (CPU_ISSET(i, &cpuset)) {
82	            std::cout << i << " ";
83	        }
84	    }
85	    std::cout << std::endl;
86	}
