94	FORCE_INLINE int choose_lru_resident_threads(
95	    const int num_reqs,
96	    const int workspace_threads,
97	    const int requested_threads
98	) {
99	    if (num_reqs <= 1) {
100	        return 1;
101	    }
102	    int active_threads = num_reqs;
103	    if (workspace_threads > 0) {
104	        active_threads = std::min(active_threads, workspace_threads);
105	    }
106	    if (requested_threads > 0) {
107	        active_threads = std::min(active_threads, requested_threads);
108	    }
109	    return std::max(active_threads, 1);
110	}
