116	FORCE_INLINE void reset_lru_resident_row(
117	    int32_t* RESTRICT slot_to_token_row,
118	    int32_t* RESTRICT lru_slots_row,
119	    const int32_t capacity
120	) {
121	    std::fill(slot_to_token_row, slot_to_token_row + capacity, -1);
122	    for (int32_t slot = 0; slot < capacity; ++slot) {
123	        lru_slots_row[slot] = slot;
124	    }
125	}
