127	FORCE_INLINE int32_t next_lru_resident_epoch(
128	    int32_t* RESTRICT token_mark,
129	    int32_t* RESTRICT token_pos,
130	    int32_t* RESTRICT epoch,
131	    const int32_t max_token
132	) {
133	    int32_t base = epoch[0] + 1;
134	    if (UNLIKELY(base >= EPOCH_RESET_THRESHOLD)) {
135	        std::fill(token_mark, token_mark + max_token, 0);
136	        std::fill(token_pos, token_pos + max_token, -1);
137	        base = 1;
138	    }
139	    epoch[0] = base;
140	    return base;
141	}
