143	FORCE_INLINE void process_one_lru_resident_row(
144	    const int row,
145	    const int32_t topk,
146	    const int32_t capacity,
147	    const int32_t max_token,
148	    const int64_t* RESTRICT req_ids,
149	    int64_t* RESTRICT last_req_ids,
150	    const int32_t* RESTRICT topk_indices,
151	    int32_t* RESTRICT slot_to_token,
152	    int32_t* RESTRICT lru_slots,
153	    int32_t* RESTRICT current_slots,
154	    int32_t* RESTRICT miss_count,
155	    int32_t* RESTRICT miss_tokens_out,
156	    int32_t* RESTRICT miss_slots_out,
157	    int32_t* RESTRICT token_mark,
158	    int32_t* RESTRICT token_pos,
159	    int32_t* RESTRICT slot_workspace,
160	    int32_t* RESTRICT miss_positions,
161	    int32_t* RESTRICT epoch
162	) {
163	    int32_t* RESTRICT slot_to_token_row = slot_to_token + static_cast<int64_t>(row) * capacity;
164	    int32_t* RESTRICT lru_slots_row = lru_slots + static_cast<int64_t>(row) * capacity;
165	    int32_t* RESTRICT current_slots_row = current_slots + static_cast<int64_t>(row) * topk;
166	    int32_t* RESTRICT miss_tokens_row = miss_tokens_out + static_cast<int64_t>(row) * topk;
167	    int32_t* RESTRICT miss_slots_row = miss_slots_out + static_cast<int64_t>(row) * topk;
168	    const int32_t* RESTRICT topk_row = topk_indices + static_cast<int64_t>(row) * topk;
169	    int32_t* RESTRICT hit_slots = slot_workspace;
170	    int32_t* RESTRICT evictable_slots = slot_workspace + capacity;
171	    int32_t* RESTRICT assigned_miss_slots = slot_workspace + static_cast<int64_t>(capacity) * 2;
172	
173	    std::fill(current_slots_row, current_slots_row + topk, -1);
174	    std::fill(miss_tokens_row, miss_tokens_row + topk, -1);
175	    std::fill(miss_slots_row, miss_slots_row + topk, -1);
176	    miss_count[row] = 0;
177	
178	    const int64_t req_id = req_ids[row];
179	    if (UNLIKELY(last_req_ids[row] != req_id)) {
180	        reset_lru_resident_row(slot_to_token_row, lru_slots_row, capacity);
181	        last_req_ids[row] = req_id;
182	    }
183	
184	    const int32_t base = next_lru_resident_epoch(token_mark, token_pos, epoch, max_token);
185	    for (int32_t pos = 0; pos < topk; ++pos) {
186	        const int32_t token = topk_row[pos];
187	        if (LIKELY(is_valid_lru_resident_token(token, max_token)) && token_mark[token] != base) {
188	            token_mark[token] = base;
189	            token_pos[token] = pos;
190	        }
191	    }
192	
193	    int32_t hit_count = 0;
194	    int32_t evictable_count = 0;
195	    for (int32_t order = 0; order < capacity; ++order) {
196	        const int32_t slot = lru_slots_row[order];
197	        if (UNLIKELY(slot < 0 || slot >= capacity)) {
198	            continue;
199	        }
200	        const int32_t token = slot_to_token_row[slot];
201	        if (LIKELY(is_valid_lru_resident_token(token, max_token)) && token_mark[token] == base) {
202	            const int32_t pos = token_pos[token];
203	            current_slots_row[pos] = slot;
204	            hit_slots[hit_count] = slot;
205	            ++hit_count;
206	        } else {
207	            evictable_slots[evictable_count] = slot;
208	            ++evictable_count;
209	        }
210	    }
211	
212	    int32_t local_miss_count = 0;
213	    for (int32_t pos = 0; pos < topk; ++pos) {
214	        const int32_t token = topk_row[pos];
215	        if (LIKELY(is_valid_lru_resident_token(token, max_token)) && current_slots_row[pos] < 0) {
216	            miss_tokens_row[local_miss_count] = token;
217	            miss_positions[local_miss_count] = pos;
218	            ++local_miss_count;
219	        }
220	    }
221	
222	    const int32_t assign_count = std::min(local_miss_count, evictable_count);
223	    for (int32_t miss_idx = 0; miss_idx < assign_count; ++miss_idx) {
224	        const int32_t slot = evictable_slots[miss_idx];
225	        const int32_t token = miss_tokens_row[miss_idx];
226	        const int32_t pos = miss_positions[miss_idx];
227	        slot_to_token_row[slot] = token;
228	        current_slots_row[pos] = slot;
229	        miss_slots_row[miss_idx] = slot;
230	        assigned_miss_slots[miss_idx] = slot;
231	        miss_count[row] = miss_idx + 1;
232	    }
233	
234	    int32_t write_pos = 0;
235	    for (int32_t idx = assign_count; idx < evictable_count; ++idx) {
236	        lru_slots_row[write_pos] = evictable_slots[idx];
237	        ++write_pos;
238	    }
239	    for (int32_t idx = 0; idx < assign_count; ++idx) {
240	        lru_slots_row[write_pos] = assigned_miss_slots[idx];
241	        ++write_pos;
242	    }
243	    for (int32_t idx = 0; idx < hit_count; ++idx) {
244	        lru_slots_row[write_pos] = hit_slots[idx];
245	        ++write_pos;
246	    }
247	}
