249	HOT_FUNCTION void lru_resident_compact(
250	    uintptr_t req_ids_ptr,
251	    uintptr_t last_req_ids_ptr,
252	    uintptr_t topk_indices_ptr,
253	    uintptr_t slot_to_token_ptr,
254	    uintptr_t lru_slots_ptr,
255	    uintptr_t current_slots_ptr,
256	    uintptr_t miss_count_ptr,
257	    uintptr_t miss_tokens_ptr,
258	    uintptr_t miss_slots_ptr,
259	    uintptr_t token_mark_workspace_ptr,
260	    uintptr_t token_pos_workspace_ptr,
261	    uintptr_t slot_workspace_ptr,
262	    uintptr_t miss_position_workspace_ptr,
263	    uintptr_t epochs_ptr,
264	    int64_t num_reqs,
265	    int64_t topk,
266	    int64_t capacity,
267	    int64_t max_token,
268	    int64_t workspace_threads,
269	    int64_t requested_threads
270	) {
271	    if (num_reqs <= 0 || topk <= 0 || capacity <= 0 || max_token <= 0) {
272	        return;
273	    }
274	
275	    auto* RESTRICT req_ids = reinterpret_cast<int64_t*>(req_ids_ptr);
276	    auto* RESTRICT last_req_ids = reinterpret_cast<int64_t*>(last_req_ids_ptr);
277	    auto* RESTRICT topk_indices = reinterpret_cast<int32_t*>(topk_indices_ptr);
278	    auto* RESTRICT slot_to_token = reinterpret_cast<int32_t*>(slot_to_token_ptr);
279	    auto* RESTRICT lru_slots = reinterpret_cast<int32_t*>(lru_slots_ptr);
280	    auto* RESTRICT current_slots = reinterpret_cast<int32_t*>(current_slots_ptr);
281	    auto* RESTRICT miss_count = reinterpret_cast<int32_t*>(miss_count_ptr);
282	    auto* RESTRICT miss_tokens = reinterpret_cast<int32_t*>(miss_tokens_ptr);
283	    auto* RESTRICT miss_slots = reinterpret_cast<int32_t*>(miss_slots_ptr);
284	    auto* RESTRICT token_mark_workspace = reinterpret_cast<int32_t*>(token_mark_workspace_ptr);
285	    auto* RESTRICT token_pos_workspace = reinterpret_cast<int32_t*>(token_pos_workspace_ptr);
286	    auto* RESTRICT slot_workspace = reinterpret_cast<int32_t*>(slot_workspace_ptr);
287	    auto* RESTRICT miss_position_workspace = reinterpret_cast<int32_t*>(miss_position_workspace_ptr);
288	    auto* RESTRICT epochs = reinterpret_cast<int32_t*>(epochs_ptr);
289	
290	    const int num_reqs_int = static_cast<int>(num_reqs);
291	    const int topk_int = static_cast<int>(topk);
292	    const int capacity_int = static_cast<int>(capacity);
293	    const int max_token_int = static_cast<int>(max_token);
294	    const int active_threads = choose_lru_resident_threads(
295	        num_reqs_int,
296	        static_cast<int>(workspace_threads),
297	        static_cast<int>(requested_threads)
298	    );
299	
300	    if (active_threads == 1) {
301	        for (int row = 0; row < num_reqs_int; ++row) {
302	            process_one_lru_resident_row(
303	                row,
304	                topk_int,
305	                capacity_int,
306	                max_token_int,
307	                req_ids,
308	                last_req_ids,
309	                topk_indices,
310	                slot_to_token,
311	                lru_slots,
312	                current_slots,
313	                miss_count,
314	                miss_tokens,
315	                miss_slots,
316	                token_mark_workspace,
317	                token_pos_workspace,
318	                slot_workspace,
319	                miss_position_workspace,
320	                epochs
321	            );
322	        }
323	        return;
324	    }
325	
326	    #pragma omp parallel num_threads(active_threads)
327	    {
328	        const int thread_id = omp_get_thread_num();
329	        int32_t* RESTRICT token_mark = token_mark_workspace + static_cast<int64_t>(thread_id) * max_token_int;
330	        int32_t* RESTRICT token_pos = token_pos_workspace + static_cast<int64_t>(thread_id) * max_token_int;
331	        int32_t* RESTRICT slots = slot_workspace + static_cast<int64_t>(thread_id) * capacity_int * 3;
332	        int32_t* RESTRICT miss_positions = miss_position_workspace + static_cast<int64_t>(thread_id) * topk_int;
333	        int32_t* RESTRICT epoch = epochs + thread_id;
334	        for (int row = thread_id; row < num_reqs_int; row += active_threads) {
335	            process_one_lru_resident_row(
336	                row,
337	                topk_int,
338	                capacity_int,
339	                max_token_int,
340	                req_ids,
341	                last_req_ids,
342	                topk_indices,
343	                slot_to_token,
344	                lru_slots,
345	                current_slots,
346	                miss_count,
347	                miss_tokens,
348	                miss_slots,
349	                token_mark,
350	                token_pos,
351	                slots,
352	                miss_positions,
353	                epoch
354	            );
355	        }
356	    }
357	}
