359	void
360	get_kv_topk_kernel(
361	    const at::Tensor& k_nope_h, // [block_num, block_size, head_kv, nope_dim]
362	    const at::Tensor& k_pe_h, // [block_num, block_size, head_kv, rope_dim]
363	    const at::Tensor& topk_indices, // [num_token, 1, topk]
364	    const at::Tensor& actual_seq_lengths_query, // [num_reqs], == num_token if without spec decode
365	    const at::Tensor& block_table, // [num_reqs, max_block_num]
366	    const int& thread_num,
367	    at::Tensor& k_nope_topk,
368	    at::Tensor& k_pe_topk
369	) {
370	    auto k_nope = k_nope_h.contiguous();
371	    auto k_pe = k_pe_h.contiguous();
372	
373	    TORCH_CHECK(topk_indices.size(1) == 1, "topk_indices must have shape [N, 1, S]");
374	    auto topk_indices_squeezed = topk_indices.squeeze(1); // [N, S]
375	
376	    int32_t token_num = topk_indices.size(0);  // Batch size
377	    int32_t pe_dim = k_pe.size(3);    // Embedding dimension of pe
378	    int32_t num_page = k_nope.size(0);    // Number of pages
379	    int32_t page_size = k_nope.size(1);   // Page size
380	    int32_t head_kv = k_nope.size(2);      // Number of heads of key/value
381	    int32_t value_dim = k_nope.size(3); // head dim of k_nope & value
382	    int32_t sqen_len = topk_indices_squeezed.size(1);  // Source sequence length (TopK)
383	    int32_t max_num_pages = block_table.size(1);  // Max number of pages per request
384	    int32_t num_requests = actual_seq_lengths_query.size(0);
385	
386	    // auto cpu_pinned_opt = k_nope_h.options()
387	    //     .device(at::kCPU)         // 限定CPU设备
388	    //     .pinned_memory(true);     // 开启页锁定内存
389	    // at::Tensor k_nope_cpu_pinned = at::empty({token_num, sqen_len, head_kv, value_dim}, cpu_pinned_opt);
390	    // at::Tensor k_pe_cpu_pinned = at::empty({token_num, sqen_len, head_kv, pe_dim}, cpu_pinned_opt);
391	
392	    bfloat16_t* k_nope_ptr = static_cast<bfloat16_t*>(k_nope.data_ptr());
393	    bfloat16_t* k_pe_ptr = static_cast<bfloat16_t*>(k_pe.data_ptr());
394	    int32_t* topk_indices_ptr = static_cast<int32_t*>(topk_indices_squeezed.data_ptr());
395	    int32_t* actual_seq_lengths_query_ptr = static_cast<int32_t*>(actual_seq_lengths_query.data_ptr());
396	    int32_t* block_table_ptr = static_cast<int32_t*>(block_table.data_ptr());
397	
398	    // bfloat16_t* k_nope_pinned_ptr = static_cast<bfloat16_t*>(k_nope_cpu_pinned.data_ptr());
399	    // bfloat16_t* k_pe_pinned_ptr = static_cast<bfloat16_t*>(k_pe_cpu_pinned.data_ptr());
400	    bfloat16_t* k_nope_pinned_ptr = static_cast<bfloat16_t*>(k_nope_topk.data_ptr());
401	    bfloat16_t* k_pe_pinned_ptr = static_cast<bfloat16_t*>(k_pe_topk.data_ptr());
402	
403	    auto req_ids = at::empty({token_num}, at::kInt);   // at::empty，分配一块指定形状和数据类型的内存空间，创建一维张量，int32类型
404	    auto page_indices = at::empty({token_num, sqen_len}, at::kInt);   //创建二维张量
405	    auto pos_in_page = at::empty({token_num, sqen_len}, at::kInt);
406	
407	    int32_t* req_ids_ptr = req_ids.data_ptr<int32_t>();
408	    int32_t* page_indices_ptr = page_indices.data_ptr<int32_t>();
409	    int32_t* pos_in_page_ptr = pos_in_page.data_ptr<int32_t>();
410	
411	    for (int32_t r = 0; r < num_requests; ++r) {
412	        int32_t start = (r == 0) ? 0 : actual_seq_lengths_query_ptr[r - 1];
413	        int32_t end = actual_seq_lengths_query_ptr[r];
414	
415	        std::fill(req_ids_ptr + start, req_ids_ptr + end, r);
416	    }
417	
418	    // multi thread related. Currently parallel in seq_len(topk) dim.
419	    // int thread_num = 16;
420	    int size_per_thread = sqen_len / thread_num;
421	    std::vector<int> thread_size(thread_num, size_per_thread);
422	    thread_size[thread_num - 1] += sqen_len - size_per_thread * thread_num;
423	    std::vector<int> thread_start(thread_num);
424	    int cumsum = 0;
425	    for(int i = 0; i < thread_num; ++i) {
426	        thread_start[i] = cumsum;
427	        cumsum += thread_size[i];
428	    }
429	    // std::cout << "thread start: "; for(auto i : thread_start) std::cout << i << " "; std::cout << std::endl;
430	    // std::cout << "thread size: "; for(auto i : thread_size) std::cout << i << " "; std::cout << std::endl;
431	
432	    at::set_num_threads(thread_num);
433	    omp_set_num_threads(thread_num);
434	
435	    #pragma omp parallel
436	    {
437	        int tid = omp_get_thread_num();
438	        int t_start = thread_start[tid];
439	        int t_end = t_start + thread_size[tid];
440	        for (int32_t i = 0; i < token_num; ++i) {
441	            int32_t req_id = req_ids_ptr[i];
442	            // for (int32_t s = 0; s < sqen_len; ++s) {
443	            for (int32_t s = t_start; s < t_end; ++s) {
444	                int32_t global_token_pos = topk_indices_ptr[i * sqen_len + s];
445	
446	                if (global_token_pos < 0) {
447	                    continue;
448	                    // page_indices_ptr[i * sqen_len + s] = 0;
449	                    // pos_in_page_ptr[i * sqen_len + s] = 0;
450	                    // for (int32_t h = 0; h < head_kv; ++h) {
451	                    //     for (int32_t d = 0; d < value_dim; ++d) {
452	                    //         k_nope_pinned_ptr[i * sqen_len * head_kv * value_dim +
453	                    //                          s * head_kv * value_dim +
454	                    //                          h * value_dim + d] = static_cast<bfloat16_t>(0.0f);
455	                    //     }
456	                    //     for (int32_t d = 0; d < pe_dim; ++d) {
457	                    //         k_pe_pinned_ptr[i * sqen_len * head_kv * pe_dim +
458	                    //                        s * head_kv * pe_dim +
459	                    //                        h * pe_dim + d] = static_cast<bfloat16_t>(0.0f);
460	                    //     }
461	                    // }
462	                    // continue;
463	                }
464	
465	                int32_t rel_page_idx = global_token_pos / page_size;
466	                int32_t offset_in_page = global_token_pos % page_size;
467	
468	                int32_t physical_page_id = block_table_ptr[req_id * max_num_pages + rel_page_idx];
469	
470	                page_indices_ptr[i * sqen_len + s] = physical_page_id;
471	                pos_in_page_ptr[i * sqen_len + s] = offset_in_page;
472	
473	                for (int32_t h = 0; h < head_kv; ++h) {
474	                    for (int32_t d = 0; d < value_dim; ++d) {
475	                        k_nope_pinned_ptr[i * sqen_len * head_kv * value_dim +
476	                                    s * head_kv * value_dim +
477	                                    h * value_dim + d] =
478	                            k_nope_ptr[physical_page_id * page_size * head_kv * value_dim +
479	                                    offset_in_page * head_kv * value_dim +
480	                                    h * value_dim + d];
481	                    }
482	                    for (int32_t d = 0; d < pe_dim; ++d) {
483	                        k_pe_pinned_ptr[i * sqen_len * head_kv * pe_dim +
484	                                    s * head_kv * pe_dim +
485	                                    h * pe_dim + d] =
486	                            k_pe_ptr[physical_page_id * page_size * head_kv * pe_dim +
487	                                    offset_in_page * head_kv * pe_dim +
488	                                    h * pe_dim + d];
489	                    }
490	                }
491	            }
492	        }
493	    }
494	
495	    return;
496	}
