498	void
499	get_kv_topk(
500	    uintptr_t k_nope_h_ptr,
501	    uintptr_t k_pe_h_ptr,
502	    uintptr_t topk_indices_ptr,
503	    uintptr_t actual_seq_lengths_query_ptr,
504	    uintptr_t block_table_ptr,
505	    uintptr_t k_nope_topk_ptr,
506	    uintptr_t k_pe_topk_ptr,
507	    std::vector<int64_t> k_nope_h_shape, // [block_num, block_size, head_kv, nope_dim]
508	    std::vector<int64_t> k_pe_h_shape, // [block_num, block_size, head_kv, rope_dim]
509	    std::vector<int64_t> topk_indices_shape, // [num_token, 1, topk]
510	    std::vector<int64_t> actual_seq_lengths_query_shape, // [num_reqs], == num_token if without spec decode
511	    std::vector<int64_t> block_table_shape, // [num_reqs, max_block_num]
512	    std::vector<int64_t> k_nope_topk_shape, // output, [num_reqs, topk, head_kv, nope_dim]
513	    std::vector<int64_t> k_pe_topk_shape, // output, [num_reqs, topk, head_kv, rope_dim]
514	    const int& thread_num
515	) {
516	    at::Tensor k_nope_h = restore_tensor(k_nope_h_ptr, k_nope_h_shape);
517	    at::Tensor k_pe_h = restore_tensor(k_pe_h_ptr, k_pe_h_shape);
518	    at::Tensor topk_indices = restore_tensor(topk_indices_ptr, topk_indices_shape, torch::kInt);
519	    at::Tensor actual_seq_lengths_query = restore_tensor(actual_seq_lengths_query_ptr, actual_seq_lengths_query_shape, torch::kInt);
520	    at::Tensor block_table = restore_tensor(block_table_ptr, block_table_shape, torch::kInt);
521	    at::Tensor k_nope_topk = restore_tensor(k_nope_topk_ptr, k_nope_topk_shape);
522	    at::Tensor k_pe_topk = restore_tensor(k_pe_topk_ptr, k_pe_topk_shape);
523	    get_kv_topk_kernel(
524	        k_nope_h,
525	        k_pe_h,
526	        topk_indices,
