536	int32_t
537	compute_lru_resident_addrs(
538	    const at::Tensor& miss_count,
539	    const at::Tensor& miss_tokens,
540	    const at::Tensor& miss_slots,
541	    const at::Tensor& block_table,
542	    const int32_t block_size,
543	    const int32_t token_size_bytes_k,
544	    const int32_t token_size_bytes_v,
545	    const int64_t gvas_k_base,
546	    const int64_t gvas_v_base,
547	    const int64_t addr_k_base,
548	    const int64_t addr_v_base,
549	    const int32_t resident_capacity,
550	    const int32_t max_num_threads,
551	    at::Tensor& gvas_buffer,
552	    at::Tensor& addr_buffer,
553	    at::Tensor& size_buffer,
554	    at::Tensor& num_tokens_buffer
555	) {
556	    const int32_t num_reqs = miss_tokens.size(0);
557	    const int32_t topk = miss_tokens.size(1);
558	    const int32_t max_num_tokens_to_load = num_reqs * topk;
559	    const int32_t max_num_blocks = block_table.size(1);
560	    const int32_t block_size_bytes_k = block_size * token_size_bytes_k;
561	    const int32_t block_size_bytes_v = block_size * token_size_bytes_v;
562	    TORCH_CHECK(miss_count.size(0) >= num_reqs,
563	        "miss_count size not enough for loading.");
564	    TORCH_CHECK(miss_slots.size(0) == num_reqs && miss_slots.size(1) == topk,
565	        "miss_slots shape should match miss_tokens.");
566	    TORCH_CHECK(gvas_buffer.size(0) >= max_num_tokens_to_load * 2,
567	        "gvas_buffer size not enough for loading.");
568	    TORCH_CHECK(addr_buffer.size(0) >= max_num_tokens_to_load * 2,
569	        "addr_buffer size not enough for loading.");
570	    TORCH_CHECK(size_buffer.size(0) >= max_num_tokens_to_load * 2,
571	        "size_buffer size not enough for loading.");
572	    TORCH_CHECK(miss_count.scalar_type() == at::kInt,
573	        "miss_count wrong dtype, should be int32.");
574	    TORCH_CHECK(miss_tokens.scalar_type() == at::kInt,
575	        "miss_tokens wrong dtype, should be int32.");
576	    TORCH_CHECK(miss_slots.scalar_type() == at::kInt,
577	        "miss_slots wrong dtype, should be int32.");
578	    TORCH_CHECK(block_table.scalar_type() == at::kInt,
579	        "block_table wrong dtype, should be int32.");
580	    TORCH_CHECK(gvas_buffer.scalar_type() == at::kLong,
581	        "gvas_buffer wrong dtype, should be int64.");
582	    TORCH_CHECK(addr_buffer.scalar_type() == at::kLong,
583	        "addr_buffer wrong dtype, should be int64.");
584	    TORCH_CHECK(size_buffer.scalar_type() == at::kInt,
585	        "size_buffer wrong dtype, should be int32.");
586	
587	    const int32_t* miss_count_ptr = static_cast<int32_t*>(miss_count.data_ptr());
588	    const int32_t* miss_tokens_ptr = static_cast<int32_t*>(miss_tokens.data_ptr());
589	    const int32_t* miss_slots_ptr = static_cast<int32_t*>(miss_slots.data_ptr());
590	    const int32_t* block_table_ptr = static_cast<int32_t*>(block_table.data_ptr());
591	    int64_t* gvas_buffer_ptr = static_cast<int64_t*>(gvas_buffer.data_ptr());
592	    int64_t* addr_buffer_ptr = static_cast<int64_t*>(addr_buffer.data_ptr());
593	    int32_t* size_buffer_ptr = static_cast<int32_t*>(size_buffer.data_ptr());
594	    int32_t* num_tokens_buffer_ptr = static_cast<int32_t*>(num_tokens_buffer.data_ptr());
595	
596	    int n_threads = std::min(num_reqs, max_num_threads);
597	    n_threads = std::max(n_threads, 1);
598	
599	    std::vector<int32_t> num_tokens_to_load_req(num_reqs);
600	    #pragma omp parallel for num_threads(n_threads)
601	    for (size_t req_idx = 0; req_idx < num_reqs; ++req_idx) {
602	        int32_t count = miss_count_ptr[req_idx];
603	        count = std::max(count, 0);
604	        count = std::min(count, topk);
605	        num_tokens_to_load_req[req_idx] = count;
606	    }
607	    int32_t num_tokens_to_load_sum = std::accumulate(num_tokens_to_load_req.begin(), num_tokens_to_load_req.end(), 0);
608	    std::vector<int32_t> req_start_locs(num_reqs);
609	    int32_t cumsum = 0;
610	    for (size_t req_idx = 0; req_idx < num_reqs; ++req_idx) {
611	        req_start_locs[req_idx] = cumsum;
612	        cumsum += num_tokens_to_load_req[req_idx];
613	    }
614	
615	    #pragma omp parallel for num_threads(n_threads)
616	    for (size_t req_idx = 0; req_idx < num_reqs; ++req_idx) {
617	        int32_t req_start_loc_k = req_start_locs[req_idx];
618	        int32_t req_start_loc_v = num_tokens_to_load_sum + req_start_loc_k;
619	        for (int32_t idx = 0; idx < num_tokens_to_load_req[req_idx]; ++idx) {
620	            const int32_t token = miss_tokens_ptr[req_idx * topk + idx];
621	            const int32_t slot = miss_slots_ptr[req_idx * topk + idx];
622	            if (token < 0 || slot < 0 || slot >= resident_capacity) {
623	                continue;
624	            }
625	            const int32_t block_id = token / block_size;
626	            if (block_id < 0 || block_id >= max_num_blocks) {
627	                continue;
628	            }
629	            const int32_t offset_in_block = token % block_size;
630	            const int32_t block_indice = block_table_ptr[req_idx * max_num_blocks + block_id];
631	            const int64_t gvas_k =
632	                gvas_k_base + block_indice * block_size_bytes_k + offset_in_block * token_size_bytes_k;
633	            const int64_t gvas_v =
634	                gvas_v_base + block_indice * block_size_bytes_v + offset_in_block * token_size_bytes_v;
635	            const int64_t addr_k = addr_k_base + (req_idx * resident_capacity + slot) * token_size_bytes_k;
636	            const int64_t addr_v = addr_v_base + (req_idx * resident_capacity + slot) * token_size_bytes_v;
637	            gvas_buffer_ptr[req_start_loc_k + idx] = gvas_k;
638	            gvas_buffer_ptr[req_start_loc_v + idx] = gvas_v;
639	            addr_buffer_ptr[req_start_loc_k + idx] = addr_k;
640	            addr_buffer_ptr[req_start_loc_v + idx] = addr_v;
641	        }
642	    }
643	
644	    std::fill_n(size_buffer_ptr, num_tokens_to_load_sum, token_size_bytes_k);
645	    std::fill_n(&(size_buffer_ptr[num_tokens_to_load_sum]), num_tokens_to_load_sum, token_size_bytes_v);
646	
647	    num_tokens_buffer_ptr[0] = num_tokens_to_load_sum * 2;
648	    return num_tokens_to_load_sum;
649	}
650	
651	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m)
652	{
653	    namespace py = pybind11;
654	    m.def("get_kv_topk", &get_kv_topk, "High performance topk combine");
655	    m.def("lru_resident_compact", &lru_resident_compact,
656	          "CPU LRU resident compact miss prepare with OpenMP row-level parallelism");
657	    m.def("compute_lru_resident_addrs", &compute_lru_resident_addrs,
658	          "Compute sparse H2D metadata for compact LRU resident miss loads");
659	}
